from pathlib import Path
import json,shutil,hashlib,re
R=Path(__file__).resolve().parent;P=R/'Saved Model/stage3_target_aware_audit_v2'
read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
a=read(P/'analysis_summary.json');v=read(P/'verification.json');assert v['passed'] and v['analysis_sha256']==sha(P/'analysis_summary.json')
paths=['Progress.txt','Current_Model_Explanation.txt','Research Paper/Readiness_and_Evidence.md','Research Paper/BioNutriGPT_Manuscript_v2.md','Research Paper/Stage3_Target_Aware_Experiment_v1.md'];archive=P/'original_documents';archive.mkdir(exist_ok=True)
for name in paths:
 if not (archive/Path(name).name).exists():shutil.copy2(R/name,archive/Path(name).name)
table='| Target source | A valid plans | B valid plans | A mean target error | B mean target error | Paired error difference, 95% CI |\n| --- | ---: | ---: | ---: | ---: | --- |\n'
for arm,c in zip(['rules_only','minimum_change','model_guided'],a['contrasts'][:3]):
 s=a['summary'][arm];d=c['distance'];e=d['difference'];table+=f"| {arm} | {s['variant_a']['accepted']}/300 | {s['variant_b']['accepted']}/300 | {d['b_mean']['mean_difference']:.4f} | {d['a_mean']['mean_difference']:.4f} | {e['mean_difference']:.4f} [{e['ci95'][0]:.4f}, {e['ci95'][1]:.4f}] |\n"
text='The target-aware experimental optimizer reduced target error among jointly successful pairs, but produced fewer valid plans under the tested three-second budget. Acceptance counts were unchanged by fresh constraint verification. These are exploratory results on the reused 100-participant cohort, which also appeared in development tests; they are not independent validation.'
methods='Continuous means and 10,000-resample confidence intervals now both weight participants equally. Within each participant, only jointly successful matched dietary modes contribute. The three within-arm distance contrasts use 259, 257 and 257 paired cells respectively; available participant counts are recorded in analysis_summary.json. Missing plans have no target-error value. Binary endpoints retain all 100 participants and all modes; pooled intervals resample participant clusters. Per-mode exact tests are exploratory with retrospective Holm adjustment across 18 contrasts per endpoint, and intervals remain pointwise. The earlier p < 1e-15 statement is withdrawn.'
limits='The archive contains status labels and gaps but omits raw solver codes, messages and incumbent flags. Therefore labels cannot independently prove optimality, lack of any incumbent, or mathematical feasibility for timed-out cases. The 299/300 mathematical-feasibility claim and the untested 5–10-second deployment recommendation are withdrawn. Variant A always ran before B; recorded runtimes are descriptive. The historical protocol was rewritable, so current hash agreement does not retrospectively establish preregistration. Engineering normalization scales are not uniformly official FDA/RDA values.'
baskets=f"Among {a['joint_success_pairs']} jointly successful pairs, {a['different_joint_baskets']} baskets differed and {a['identical_joint_baskets']} were identical. The old 887/900 statistic conflated meal changes with failed empty outputs."
verify='Fresh replay reconstructed all 900 input fingerprints, checked 1,800 outputs against food quantities, serving/category rules, dietary exclusions, active nutrient coverage/bounds, energy, macro fractions, fiber density and sodium/potassium rules. Target errors were recomputed from catalog totals and upstream targets. Four corruption checks passed. A separate implementation verified 30 confidence intervals, 36 exact paired tests, multiplicity adjustments and summary counts/timings. Food parsing, bound construction and the earlier independent arithmetic checker are shared dependencies; neither production acceptance flags nor saved replay flags determine audit decisions. Original records remained unchanged and no solver was called.'
report='# Stage 3 target-aware experiment: corrected audit v2\n\nUpdated 23 November 2026. Existing-record correction; no production changes or solver reruns.\n\n'+text+'\n\n'+table+'\n'+methods+'\n\n'+baskets+'\n\n'+limits+'\n\n'+verify+'\n\nEvidence: `Saved Model/stage3_target_aware_audit_v2/analysis_summary.json`, `recomputed_LOCAL.json`, `replay_verification.json`, `verification.json` and `input_manifest.json`. Historical documents are retained in `original_documents/`; original experimental checkpoints are untouched.\n\nThe new objective improves the metric it directly optimizes, conditional on successful plans. That is not proof of clinical benefit or that model-guided targets are superior to simpler targets. Keep this optimizer experimental. A separately frozen budget experiment on an independent sample would be needed to assess longer-runtime trade-offs; none was run here.\n'
(R/'Research Paper/Stage3_Target_Aware_Audit_v2.md').write_text(report,encoding='utf-8')
(R/'Research Paper/Stage3_Target_Aware_Experiment_v1.md').write_text('# Historical report — superseded\n\nUse [corrected audit v2](Stage3_Target_Aware_Audit_v2.md). The original report is retained in `Saved Model/stage3_target_aware_audit_v2/original_documents/`. Original experiment artifacts remain unchanged.\n',encoding='utf-8')
note='STAGE 3 TARGET-AWARE EXISTING-RECORD AUDIT v2 — 2026-11-23\n'+text+'\n'+verify+'\nReport: Research Paper/Stage3_Target_Aware_Audit_v2.md. Original statistical weighting, basket-change and unsupported solver/deployment claims are superseded.\n\n'
p=R/'Progress.txt';s=p.read_text(encoding='utf-8-sig');marker='STAGE 3 TARGET-AWARE EXPERIMENTAL OPTIMIZER STUDY COMPLETE'
if marker in s:s=s[:s.index(marker)]+'Historical target-aware v1 entry archived in Saved Model/stage3_target_aware_audit_v2/original_documents/Progress.txt.\n'
p.write_text(note+s,encoding='utf-8')
p=R/'Current_Model_Explanation.txt';s=p.read_text(encoding='utf-8-sig');marker='STAGE 2 TO STAGE 3 EXISTING-RECORD AUDIT';assert marker in s;p.write_text(note+s[s.index(marker):],encoding='utf-8')
p=R/'Research Paper/Readiness_and_Evidence.md';s=p.read_text(encoding='utf-8-sig');marker='## Corrected translation audit';assert marker in s;p.write_text('## Corrected target-aware experiment\n\n'+text+'\n\n'+verify+'\n\nSee Stage3_Target_Aware_Audit_v2.md.\n\n'+s[s.index(marker):],encoding='utf-8')
p=R/'Research Paper/BioNutriGPT_Manuscript_v2.md';s=p.read_text(encoding='utf-8-sig');start=s.index('### 3.4.1 Stage 3 target-aware');end=s.index('### 3.5 Historical',start);p.write_text(s[:start]+'### 3.4.1 Target-aware experimental optimizer: retrospective corrected audit\n\n'+text+'\n\n'+table+'\n'+methods+'\n\n'+baskets+'\n\n'+limits+'\n\nSee Stage3_Target_Aware_Audit_v2.md for independent record replay and statistical verification. Production behavior was unchanged.\n\n'+s[end:],encoding='utf-8')
(P/'document_sync.json').write_text(json.dumps({name:sha(R/name) for name in paths},indent=2));print(table)
